"""Run short child jobs, reap them, and append their exit statuses."""

import errno
import fcntl
import os
import sys
import time

BASE = os.path.dirname(os.path.abspath(__file__))
RESULTS = os.path.join(BASE, "results.tsv")
HEADER = "run\tjob\texit_status\n"


def usage():
    sys.stderr.write("usage: %s JOB_COUNT\n" % sys.argv[0])
    return 2


def record_result(run_id, job_number, exit_status):
    # Serialize each append so concurrent supervisors cannot interleave records.
    with open(RESULTS, "a+") as result_file:
        fcntl.flock(result_file.fileno(), fcntl.LOCK_EX)
        result_file.seek(0, os.SEEK_END)
        if result_file.tell() == 0:
            result_file.write(HEADER)
        result_file.write("%s\t%d\t%d\n" % (run_id, job_number, exit_status))
        result_file.flush()
        os.fsync(result_file.fileno())
        fcntl.flock(result_file.fileno(), fcntl.LOCK_UN)


def child_status(wait_status):
    if os.WIFEXITED(wait_status):
        return os.WEXITSTATUS(wait_status)
    if os.WIFSIGNALED(wait_status):
        return 128 + os.WTERMSIG(wait_status)
    return None


def main():
    if len(sys.argv) != 2:
        return usage()
    try:
        job_count = int(sys.argv[1])
    except ValueError:
        return usage()
    if job_count < 0:
        return usage()

    run_id = "%d-%d" % (int(time.time() * 1000000), os.getpid())
    children = {}
    fork_error = None

    for number in range(job_count):
        try:
            pid = os.fork()
        except OSError as exc:
            fork_error = exc
            break
        if pid == 0:
            time.sleep(0.1)
            os._exit(0 if number % 2 == 0 else 3)
        children[pid] = number

    # Remain alive until every child that was started has been waited for.
    while children:
        try:
            pid, wait_status = os.wait()
        except OSError as exc:
            if exc.errno == errno.EINTR:
                continue
            raise
        if pid not in children:
            continue
        status = child_status(wait_status)
        if status is None:
            continue
        record_result(run_id, children.pop(pid), status)

    if fork_error is not None:
        sys.stderr.write("could not start all jobs: %s\n" % fork_error)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())
